def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []

    # Collect marker coordinates by color.
    pts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                pts.setdefault(grid[r][c], []).append((r, c))

    # The 1-marker makes a short horizontal trail and a translated 1.
    for r, c in pts.get(1, []):
        path = [(r, c), (r, c + 1), (r, c + 2)]
        if c + 2 < w:
            paths.append(path)
            out[r - 1][c + 2] = 1
            for rr, cc in path[1:]:
                if out[rr][cc] == 0:
                    out[rr][cc] = 5

    # 2 extends four cells left, 3 three cells down, and 6 six cells up.
    for color, dr, dc, length in [(2, 0, -1, 4), (3, 1, 0, 3), (6, -1, 0, 6)]:
        for r, c in pts.get(color, []):
            path = [(r + dr * k, c + dc * k) for k in range(length + 1)]
            if all(0 <= rr < h and 0 <= cc < w for rr, cc in path):
                paths.append(path)
                for rr, cc in path[1:-1]:
                    if out[rr][cc] == 0:
                        out[rr][cc] = 5
                rr, cc = path[-1]
                out[rr][cc] = color

    # Intersections of trails become 4.
    counts = {}
    for path in paths:
        for cell in path:
            counts[cell] = counts.get(cell, 0) + 1

    crossings = []
    for (r, c), count in counts.items():
        if count > 1:
            out[r][c] = 4
            crossings.append((r, c))

    # A crossing sends a diagonal trail of 4s down-left.
    for r, c in crossings:
        r += 1
        c -= 1
        while r < h and c >= 0:
            out[r][c] = 4
            r += 1
            c -= 1

    return out
